r(S.SELLERSKU) = lower(O.SKU) where lower(MarketplaceName) = \'amazon.de\' order by POSTEDDATE desc; CREATE OR REPLACE TABLE vahdam_db.maplemonk.ASP_DE_ASIN_Payment_Reports_Budget_Tracking_order_level AS with Payments as ( select POSTEDDATE::date as Date ,AMAZONORDERID ,ASIN ,MarketplaceName ,sum(ifnull(PRINCIPAL,0))+sum(ifnull(PROMOTION,0))+sum(ifnull(TAX,0))+sum(ifnull(REFUND_TAX,0))+sum(ifnull(REFUND_PRINCIPAL,0))+sum(ifnull(REFUND_PROMOTION,0))+sum(ifnull(REFUND_SHIPPINGTAX,0))+sum(ifnull(REFUND_SHIPPINGCHARGE,0))+sum(ifnull(REFUND_GIFTWRAP,0))+sum(ifnull(REFUND_GIFTWRAPTAX,0))+sum(ifnull(REFUND_EXPORTCHARGE,0))+sum(ifnull(REFUND_RETURNSHIPPING,0))+sum(ifnull(REFUND_GENERICDEDUCTION,0))+sum(ifnull(REFUND_GOODWILL,0))+sum(ifnull(REFUND_GIFTWRAPCHARGEBACK,0))+sum(ifnull(REFUND_SHIPPINGCHARGEBACK,0))+sum(ifnull(REFUND_MARKETPLACEFACILITATORTAX_OTHER,0))+sum(ifnull(REFUND_MARKETPLACEFACILITATORVAT_SHIPPING,0))+sum(ifnull(REFUND_MARKETPLACEFACILITATORVAT_PRINCIPAL,0))+sum(ifnull(GIFTWRAP,0))+sum(ifnull(GIFTWRAPTAX,0))+sum(ifnull(SHIPPINGCHARGE,0))+sum(ifnull(SHIPPINGTAX,0))+sum(ifnull(MARKETPLACEFACILITATORTAXOTHER,0))+sum(ifnull(MARKETPLACEFACILITATORVATSHIPPING,0))+sum(ifnull(MARKETPLACEFACILITATORVATPRINCIPAL,0))+sum(ifnull(FIXEDCLOSINGFEE,0))+sum(ifnull(GIFTWRAPCHARGEBACK,0))+sum(ifnull(SHIPPINGCHARGEBACK,0))+sum(ifnull(VARIABLECLOSINGFEE,0)) as Sales ,-1*sum(ifnull(FBAPERUNITFULFILLMENTFEE,0)) as FBA_Fees ,-1*(sum(ifnull(Commission,0))+sum(ifnull(REFUND_COMMISSION,0))+sum(ifnull(REFUND_REFUNDCOMMISSION,0))) as Commission ,sum(ifnull(quantity,0)) as Quantity_sold ,sum(ifnull(refund_quantity,0)) Refund_Quanity ,sum(ifnull(quantity,0))-sum(ifnull(refund_quantity,0)) as Units from vahdam_db.maplemonk.VAHDAM_ASP_DE_REFUND_SHIPMENT_ORDER_ID group by 1,2,3,4 ), ADJUSTMENT AS (select posteddate::DATE AS DATE ,O.ASIN ,sum(ifnull(COMPENSATED_CLAWBACK_QUANTITY,0)) + sum(ifnull(WAREHOUSE_DAMAGE_QUANTITY,0)) + sum(ifnull(REVERSAL_REIMBURSEMENT_QUANTITY,0)) + sum(ifnull(WAREH