e(P.date,ADJ.DATE,A.date,AD.date_value,B.Budget_month,R.DATE))= S.YEAR LEFT JOIN COB_LIB CL ON LOWER(coalesce(P.ASIN,ADJ.ASIN,A.asin,AD.ASIN,B.ASIN,M.\"Amazon AUS\"))=LOWER(CL.ASIN) order by Date desc; Create or replace table vahdam_db.maplemonk.VAHDAM_ASP_UAE_REFUND_SHIPMENT_ORDER_ID_order_level as With Refund as (Select POSTEDDATE::date as POSTEDDATE ,AMAZONORDERID ,SELLERSKU ,MarketplaceName ,sum(ifnull(Tax,0)) Refund_Tax ,sum(ifnull(Principal,0)) Refund_Principal ,sum(ifnull(ShippingTax,0)) Refund_ShippingTax ,sum(ifnull(ShippingCharge,0)) Refund_ShippingCharge ,sum(ifnull(PaymentMethodFee,0)) Refund_PaymentMethodFee ,sum(ifnull(Commission,0)) Refund_Commission ,sum(ifnull(RefundCommission,0)) Refund_RefundCommission ,sum(ifnull(CODChargeback,0)) Refund_CODChargeback ,sum(ifnull(ShippingChargeback,0)) Refund_ShippingChargeback ,sum(ifnull(Quantity,0)) Refund_Quantity ,sum(ifnull(Refund_Promotion,0)) Refund_Promotion from vahdam_db.maplemonk.vahdam_UAE_refund_event_list group by 1,2,3,4), Shipment as (select POSTEDDATE::date as POSTEDDATE ,AMAZONORDERID ,SELLERSKU ,MarketplaceName ,sum(ifnull(Principal,0)) Principal ,sum(ifnull(Tax,0)) Tax ,sum(ifnull(GiftWrap,0)) GiftWrap ,sum(ifnull(GiftWrapTax,0)) GiftWrapTax ,sum(ifnull(ShippingCharge,0)) ShippingCharge ,sum(ifnull(ShippingTax,0)) ShippingTax ,sum(ifnull(Paymentmethodfee,0)) Paymentmethodfee ,sum(ifnull(FBAPerUnitFulfillmentFee,0)) FBAPerUnitFulfillmentFee ,sum(ifnull(Commission,0)) Commission ,sum(ifnull(FixedclosingFee,0)) FixedclosingFee ,sum(ifnull(ShippingChargeback,0)) ShippingChargeback ,sum(ifnull(VariableClosingFee,0)) VariableClosingFee ,sum(ifnull(Codchargeback,0)) Codchargeback ,sum(ifnull(Quantity,0)) Quantity ,sum(ifnull(Promotion,0)) Promotion from vahdam_db.maplemonk.vahdam_UAE_shipment_event_list group by 1,2,3,4), Orders as ( select * from (select SKU , ASIN , row_number() over (partition by SKU order by ASIN) rw from ( select distinct SKU, ASIN from vahdam_db.maplemonk.asp_uae_get_flat_file