les,0)) OVER (PARTITION BY COALESCE(P.date,ADJ.DATE,A.date,AD.date_value,B.Budget_month,R.DATE),COALESCE(P.ASIN, ADJ.ASIN, A.asin, AD.ASIN, B.ASIN, M.\"Amazon UAE\", CL.ASIN))) as Daily_Budget_Storage_INR ,B.Budget_FBA_INR/dayofmonth(last_day(coalesce(p.date,b.budget_month)))*div0(IFNULL(P.Sales,0), SUM(IFNULL(P.sales,0)) OVER (PARTITION BY COALESCE(P.date,ADJ.DATE,A.date,AD.date_value,B.Budget_month,R.DATE),COALESCE(P.ASIN, ADJ.ASIN, A.asin, AD.ASIN, B.ASIN, M.\"Amazon UAE\", CL.ASIN))) as Daily_Budget_FBA_INR ,B.Budget_CM1_INR/dayofmonth(last_day(coalesce(p.date,b.budget_month)))*div0(IFNULL(P.Sales,0), SUM(IFNULL(P.sales,0)) OVER (PARTITION BY COALESCE(P.date,ADJ.DATE,A.date,AD.date_value,B.Budget_month,R.DATE),COALESCE(P.ASIN, ADJ.ASIN, A.asin, AD.ASIN, B.ASIN, M.\"Amazon UAE\", CL.ASIN))) as Daily_Budget_CM1_INR ,B.Budget_PM_SPEND_INR/dayofmonth(last_day(coalesce(p.date,b.budget_month)))*div0(IFNULL(P.Sales,0), SUM(IFNULL(P.sales,0)) OVER (PARTITION BY COALESCE(P.date,ADJ.DATE,A.date,AD.date_value,B.Budget_month,R.DATE),COALESCE(P.ASIN, ADJ.ASIN, A.asin, AD.ASIN, B.ASIN, M.\"Amazon UAE\", CL.ASIN))) as Daily_Budget_PM_SPEND_INR ,B.Budget_CM2_INR/dayofmonth(last_day(coalesce(p.date,b.budget_month)))*div0(IFNULL(P.Sales,0), SUM(IFNULL(P.sales,0)) OVER (PARTITION BY COALESCE(P.date,ADJ.DATE,A.date,AD.date_value,B.Budget_month,R.DATE),COALESCE(P.ASIN, ADJ.ASIN, A.asin, AD.ASIN, B.ASIN, M.\"Amazon UAE\", CL.ASIN))) as Daily_Budget_CM2_INR ,CASE WHEN S.STFS_CURRENT_MONTH = 0 THEN S.STFS_LAST_MONTH ELSE S.STFS_CURRENT_MONTH END*div0(ifnull(P.Sales,0),sum(ifnull(P.sales,0)) over (partition by coalesce(P.date,ADJ.DATE,A.date,AD.date_value,B.Budget_month,R.DATE) order by coalesce(P.date,ADJ.DATE,A.date,AD.date_value,B.Budget_month,R.DATE)))/31 STSF ,CASE WHEN S.LTFS_CURRENT_MONTH = 0 THEN S.LTFS_LAST_MONTH ELSE S.LTFS_CURRENT_MONTH END* div0(ifnull(P.Sales,0),sum(ifnull(P.sales,0)) over (partition by coalesce(P.date,ADJ.DATE,A.date,AD.date_value,B.Budget_month,R.DATE) order by coalesce(P.date,ADJ.DATE,A.date,AD.date_value,B.Budget_month,R.DATE)))/31 LTSF ,M.weight ,M.brand ,M.\"Mother SKU\" ,M.\"Common Name\" ,M.category ,M.\"SUB CATEGORY\" ,M.\"LOOSE/TEA BAG/ POWDER\" ,M.\"Common SKU Description\" ,M.\"COMMON SKU ID\" from ASINDATE AD full outer join payments P on AD.date_value = P.date and AD.ASIN = P.ASIN FULL OUTER JOIN ADJUSTMENT ADJ ON COALESCE(AD.DATE_VALUE,P.DATE) = ADJ.DATE AND COALESCE(AD.ASIN,P.ASIN) = ADJ.ASIN full outer join AMAZONADS A on coalesce(AD.date_value,P.Date) = A.date and coalesce(AD.ASIN,P.ASIN) = A.ASIN full outer join Budget B on coalesce(date_trunc(\'month\',P.Date),date_trunc(\'month\',A.Date),date_trunc(\'month\',AD.date_value)) = date_trunc(\'month\',B.Budget_month) and coalesce(P.ASIN,A.ASIN,AD.ASIN) = B.ASIN LEFT JOIN REMOVALDISPOSAL R ON coalesce(P.date,ADJ.DATE,A.date,AD.date_value,B.Budget_month)=R.DATE left join MAPPING M on lower(coalesce(P.ASIN,B.ASIN,A.ASIN,AD.ASIN)) = lower(M.\"Amazon UAE\") LEFT JOIN STORAGE S ON MONTH(coalesce(P.date,ADJ.DATE,A.date,AD.date_value,B.Budget_month,R.DATE)) = S.MONTH AND YEAR(coalesce(P.date,ADJ.DATE,A.date,AD.date_value,B.Budget_month,R.DATE))= S.YEAR LEFT JOIN COB_LIB CL ON LOWER(coalesce(P.ASIN,ADJ.ASIN,A.asin,AD.ASIN,B.ASIN,M.\"Amazon UAE\"))=LOWER(CL.ASIN) order by Date desc; Create or replace table vahdam_db.maplemonk.VAHDAM_ASP_UAE_REFUND_SHIPMENT_ORDER_ID_order_level as With Refund as (Select POSTEDDATE::date as POSTEDDATE ,AMAZONORDERID ,SELLERSKU ,MarketplaceName ,sum(ifnull(Tax,0)) Refund_Tax ,sum(ifnull(Principal,0)) Refund_Principal ,sum(ifnull(ShippingTax,0)) Refund_ShippingTax ,sum(ifnull(ShippingCharge,0)) Refund_ShippingCharge ,sum(ifnull(PaymentMethodFee,0)) Refund_PaymentMethodFee ,sum(ifnull(Commission,0)) Refund_Commission ,sum(ifnull(RefundCommission,0)) Refund_RefundCommission ,sum(ifnull(CODChargeback,0)) Refund_CODChargeback ,sum(ifnull(ShippingChargeback,0)) Refund_ShippingChargeback ,sum(ifnull(Quantity,0)) Refund_Quantity ,sum(ifnull(Refund_Promotion,0)) Refund_Promotion from vahdam_db.maplemonk.vahdam_UAE_refund_event_list group by 1,2,3,4), Shipment as (select POSTEDDATE::date as POSTEDDATE ,AMAZONORDERID ,SELLERSKU ,MarketplaceName ,sum(ifnull(Principal,0)) Principal ,sum(ifnull(Tax,0)) Tax ,sum(ifnull(GiftWrap,0)) GiftWrap ,sum(ifnull(GiftWrapTax,0)) GiftWrapTax ,sum(ifnull(ShippingCharge,0)) ShippingCharge ,sum(ifnull(ShippingTax,0)) ShippingTax ,sum(ifnull(Paymentmethodfee,0)) Paymentmethodfee ,sum(ifnull(FBAPerUnitFulfillmentFee,0)) FBAPerUnitFulfillmentFee ,sum(ifnull(Commission,0)) Commission ,sum(ifnull(FixedclosingFee,0)) FixedclosingFee ,sum(ifnull(ShippingChargeback,0)) ShippingChargeback ,sum(ifnull(VariableClosingFee,0)) VariableClosingFee ,sum(ifnull(Codchargeback,0)) Codchargeback ,sum(ifnull(Quantity,0)) Quantity ,sum(ifnull(Promotion,0)) Promotion from vahdam_db.maplemonk.vahdam_UAE_shipment_event_list group by 1,2,3,4), Orders as ( select * from (select SKU , ASIN , row_number() over (partition by SKU order by ASIN) rw from ( select distinct SKU, ASIN from vahdam_db.maplemonk.asp_uae_get_flat_file_all_orders_data_by_last_update_general where year(\"purchase-date\"::date) >= \'2023\' and lower(\"sales-channel\") = \'amazon.ae\' and sku is not null ) ) where rw=1 ) select coalesce(S.POSTEDDATE,R.POSTEDDATE)::date POSTEDDATE ,coalesce(S.AMAZONORDERID,R.AMAZONORDERID) AMAZONORDERID ,coalesce(S.SELLERSKU,R.SELLERSKU) SELLERSKU ,coalesce(S.MarketplaceName, S.MarketplaceName) MarketplaceName ,O.ASIN as ASIN ,ifnull(Principal,0) Principal ,ifnull(Tax,0) Tax ,ifnull(GiftWrap,0) GiftWrap ,ifnull(GiftWrapTax,0) GiftWrapTax ,ifnull(ShippingCharge,0) ShippingCharge ,ifnull(ShippingTax,0) ShippingTax ,ifnull(Paymentmethodfee,0) Paymentmethodfee ,ifnull(FBAPerUnitFulfillmentFee,0) FBAPerUnitFulfillmentFee ,ifnull(Commission,0) Commission ,ifnull(FixedclosingFee,0) FixedclosingFee ,ifnull(ShippingChargeback,0) ShippingChargeback ,ifnull(VariableClosingFee,0) VariableClosingFee ,ifnull(Codchargeback,0) Codchargeback ,ifnull(Quantity,0) Quantity ,ifnull(Promotion,0) Promotion ,ifnull(Refund_Tax,0) Refund_Tax ,ifnull(Refund_Principal,0) Refund_Principal ,ifnull(Refund_ShippingTax,0) Refund_ShippingTax ,ifnull(Refund_ShippingCharge,0) Refund_ShippingCharge ,ifnull(Refund_PaymentMethodFee,0) Refund_PaymentMethodFee ,ifnull(Refund_Commission,0) Refund_Commission ,ifnull(Refund_RefundCommission,0) Refund_RefundCommission ,ifnull(Refund_CODChargeback,0) Refund_CODChargeback ,ifnull(Refund_ShippingChargeback,0) Refund_ShippingChargeback ,ifnull(Refund_Quantity,0) Refund_Quantity ,ifnull(Refund_Promotion,0) Refund_Promotion from Shipment S full outer join Refund R on S.AMAZONORDERID = R.AMAZONORDERID and lower(S.SELLERSKU) = lower(R.SELLERSKU) left join Orders O on lower(S.SELLERSKU) = lower(O.SKU) where lower(coalesce(S.MarketplaceName, S.MarketplaceName)) = \'amazon.ae\' order by POSTEDDATE desc; Create or replace table vahdam_db.maplemonk.ASP_UAE_ASIN_Payment_Reports_Budget_Tracking_order_level as WITH Payments AS ( select POSTEDDATE::date as Date ,AMAZONORDERID ,ASIN ,MarketplaceName ,sum(ifnull(Principal,0))+sum(ifnull(Tax,0))+sum(ifnull(GiftWrap,0))+sum(ifnull(GiftWrapTax,0))+sum(ifnull(ShippingCharge,0))+sum(ifnull(ShippingTax,0))+sum(ifnull(Paymentmethodfee,0))+sum(ifnull(FixedclosingFee,0))+sum(ifnull(ShippingChargeback,0))+sum(ifnull(VariableClosingFee,0))+sum(ifnull(Codchargeback,0))+sum(ifnull(Promotion,0))+sum(ifnull(Refund_Tax,0))+sum(ifnull(Refund_Principal,0))+sum(ifnull(Refund_ShippingTax,0))+sum(ifnull(Refund_ShippingCharge,0))+sum(ifnull(Refund_PaymentMethodFee,0))+sum(ifnull(Refund_CODChargeback,0))+sum(ifnull(Refund_ShippingChargeback,0))+sum(ifnull(Refund_Promotion,0)) as Sales ,-1*sum(ifnull(FBAPERUNITFULFILLMENTFEE,0)) as FBA_Fees ,-1*(sum(ifnull(Commission,0))+sum(ifnull(REFUND_COMMISSION,0))+sum(ifnull(REFUND_REFUNDCOMMISSION,0))) as Commission ,sum(ifnull(quantity,0)) as Quantity_sold ,sum(ifnull(refund_quantity,0)) Refund_Quanity ,sum(ifnull(quantity,0))-sum(ifnull(refund_quantity,0)) as Units from vahdam_db.maplemonk.VAHDAM_ASP_UAE_REFUND_SHIPMENT_ORDER_ID group by 1,2,3,4 ), ADJUSTMENT AS ( select posteddate::DATE AS DATE ,O.ASIN ,sum(ifnull(COMPENSATED_CLAWBACK_QUANTITY,0)) + sum(ifnull(WAREHOUSE_DAMAGE_QUANTITY,0)) + sum(ifnull(REVERSAL_REIMBURSEMENT_QUANTITY,0)) + sum(ifnull(WAREHOUSE_LOST_MANUAL_QUANTITY,0)) + sum(ifnull(FREE_REPLACEMENT_REFUND_ITEMS_QUANTITY,0)) as TOTAL_ADJUSTMENT_QTY ,sum(ifnull(COMPENSATED_CLAWBACK_TOTAL_AMOUNT,0)) COMPENSATED_CLAWBACK_TOTAL_AMOUNT ,sum(ifnull(WAREHOUSE_DAMAGE_TOTAL_AMOUNT,0)) WAREHOUSE_DAMAGE_TOTAL_AMOUNT ,sum(ifnull(REVERSAL_REIMBURSEMENT_TOTAL_AMOUNT,0)) REVERSAL_REIMBURSEMENT_TOTAL_AMOUNT ,sum(ifnull(WAREHOUSE_LOST_MANUAL_TOTAL_AMOUNT,0)) WAREHOUSE_LOST_MANUAL_TOTAL_AMOUNT ,sum(ifnull(FREE_REPLACEMENT_REFUND_ITEMS_TOTAL_AMOUNT,0)) FREE_REPLACEMENT_REFUND_ITEMS_TOTAL_AMOUNT ,sum(ifnull(COMPENSATED_CLAWBACK_TOTAL_AMOUNT,0))+sum(ifnull(WAREHOUSE_DAMAGE_TOTAL_AMOUNT,0))+sum(ifnull(REVERSAL_REIMBURSEMENT_TOTAL_AMOUNT,0))+sum(ifnull(WAREHOUSE_LOST_MANUAL_TOTAL_AMOUNT,0))+sum(ifnull(FREE_REPLACEMENT_REFUND_ITEMS_TOTAL_AMOUNT,0)) as OTHER_SALES from vahdam_db.maplemonk.vahdam_uae_adjustment_event_list A LEFT JOIN ( select * from (select SKU , case when sku = \'Uncommingled.MSKU.1614859309584\' then \'B08Y1FH4ZP\' else ASIN end as ASIN , row_number() over (partition by SKU order by ASIN) rw from ( select distinct SKU, ASIN from Vahdam_db.maplemonk.ASP_UAE_GET_FLAT_FILE_ALL_ORDERS_DATA_BY_LAST_UPDATE_GENERAL where year(\"purchase-date\"::date) >= \'2023\' and sku is not null ) ) where rw=1 ) O ON LOWER(A.SELLERSKU) = LOWER(O.SKU) group by 1,2 ), Budget as ( Select Budget_month ,ASIN ,sum(Per_unit_Cogs) as Per_unit_Cogs ,sum(Per_unit_Outbound) as Per_unit_Outbound ,sum(Budget_units) as Budget_units ,sum(ASP) as Budget_ASP ,sum(Budget_revenue) as Budget_revenue ,sum(Budget_COGS) as Budget_COGS ,sum(Budget_Commission) as Budget_Commission ,sum(Budget_Outbound) as Budget_Outbound ,sum(Budget_Storage) as Budget_Storage ,sum(Budget_Last_mile) as Budget_FBA ,sum(Budget_PM_Spend) as Budget_PM_Spend ,sum(Budget_revenue)-sum(Budget_COGS)-sum(Budget_Commission)-sum(Budget_Outbound)-sum(Budget_Storage)-sum(Budget_Last_mile)-sum(Budget_PM_Spend) as Budget_CM2 ,sum(Budget_revenue)-sum(Budget_COGS)-sum(Budget_Commission)-sum(Budget_Outbound)-sum(Budget_Storage)-sum(Budget_Last_mile) as Budget_CM1 ,sum(ifnull(Budget_Revenue_INR,0)) Budget_Revenue_INR ,sum(ifnull(Budget_COGS_INR,0)) Budget_COGS_INR ,sum(ifnull(Budget_Commission_INR,0)) Budget_Commission_INR ,sum(ifnull(Budget_Outbound_INR,0)) Budget_Outbound_INR ,sum(ifnull(Budget_Storage_INR,0)) Budget_Storage_INR ,sum(ifnull(Budget_FBA_INR,0)) Budget_FBA_INR ,sum(ifnull(Budget_CM1_INR,0)) Budget_CM1_INR ,sum(ifnull(Budget_PM_SPEND_INR,0)) Budget_PM_SPEND_INR ,sum(ifnull(Budget_CM2_INR,0)) Budget_CM2_INR ,row_number() over (partition by Budget_month,asin order by sum(Budget_units) desc) rw from ( select try_to_date(month) as Budget_Month ,asin as ASIN ,cast(\"Per Units COGS\" as float) as Per_Unit_COGS ,cast(\"Per Unit Outbound\" as float) as Per_unit_outbound ,cast(units as float) as Budget_units ,cast(ASP as float) as ASP ,cast(Revenue as float) as Budget_revenue ,cast(COGS as float) as Budget_COGS ,cast(\"Comm \" as float) as Budget_Commission ,cast(\"Outbound \" as float) as Budget_Outbound ,cast(Storage as float) as Budget_Storage ,cast(\"Last Mile \" as float) as Budget_Last_mile ,cast(\"PM SPEND\" as float) as Budget_PM_Spend ,cast(\"Revenue(INR)\" as float) as Budget_Revenue_INR ,cast(\"REVISED COGS\" as float) as Budget_COGS_INR ,cast(\"Comm (INR)\" as float) as Budget_Commission_INR ,cast(\"Outbound(INR)\" as float) as Budget_Outbound_INR ,cast(\"Storage(INR)\" as float) as Budget_Storage_INR ,cast(\"Last Mile (INR)\" as float) as Budget_FBA_INR ,cast(\"CM1 (INR)\" as float) as Budget_CM1_INR ,cast(\"PM SPEND (INR)\" as float) as Budget_PM_SPEND_INR ,cast(\"CM2\" as float) as Budget_CM2_INR ,row_number() over (partition by month,asin order by cast(units as float) desc) rw from vahdam_db.maplemonk.gs_fy24_budget_consol_backup where lower(channel) = \'amazon\' and lower(platform) = \'uae\' UNION ALL SELECT TO_DATE(month, \'MON-YY\') AS Date, ASIN, div0( try_cast(replace(replace(COGS, \',\', \'\'), \'-\', \'\') as float), try_cast(replace(replace(UNITS, \',\', \'\'), \'-\', \'\') as float) ) AS Per_Unit_COGS, div0( try_cast(replace(replace(OUTBOUND, \',\', \'\'), \'-\', \'\') as float), try_cast(replace(replace(UNITS, \',\', \'\'), \'-\', \'\') as float) ) AS Per_Unit_Outbound, try_cast(replace(replace(UNITS, \',\', \'\'), \'-\', \'\') as float) AS Budget_Units, try_cast(replace(replace(ASP, \',\', \'\'), \'-\', \'\') as float) AS ASP, try_cast(replace(replace(REVENUE, \',\', \'\'), \'-\', \'\') as float) AS Budget_Revenue, try_cast(replace(replace(COGS, \',\', \'\'), \'-\', \'\') as float) AS Budget_COGS, try_cast(replace(replace(COMM, \',\', \'\'), \'-\', \'\') as float) AS Budget_Commission, try_cast(replace(replace(OUTBOUND, \',\', \'\'), \'-\', \'\') as float) AS Budget_Outbound, try_cast(replace(replace(STORAGE, \',\', \'\'), \'-\', \'\') as float) AS Budget_Storage, try_cast(replace(replace(\"Last Mile\", \',\', \'\'), \'-\', \'\') as float) AS Budget_Last_Mile, try_cast(replace(replace(\"PM SPEND\", \',\', \'\'), \'-\', \'\') as float) AS Budget_PM_Spend, try_cast(replace(replace(\"Revenue(INR)\", \',\', \'\'), \'-\', \'\') as float) AS Budget_Revenue_INR, try_cast(replace(replace(\"REVISED COGS\", \',\', \'\'), \'-\', \'\') as float) AS Budget_COGS_INR, try_cast(replace(replace(\"Comm (INR)\", \',\', \'\'), \'-\', \'\') as float) AS Budget_Commission_INR, try_cast(replace(replace(\"Outbound(INR)\", \',\', \'\'), \'-\', \'\') as float) AS Budget_Outbound_INR, try_cast(replace(replace(\"Storage(INR)\", \',\', \'\'), \'-\', \'\') as float) AS Budget_Storage_INR, try_cast(replace(replace(\"Last Mile (INR)\", \',\', \'\'), \'-\', \'\') as float) AS Budget_FBA_INR, try_cast(replace(replace(\"CM1(INR)\", \',\', \'\'), \'-\', \'\') as float) AS Budget_CM1_INR, try_cast(replace(replace(\"PM Spend(INR)\",\',\', \'\'), \'-\', \'\') as float) AS Budget_PM_SPEND_INR, try_cast(replace(replace(\"CM2(INR)\", \',\', \'\'), \'-\', \'\') as float) AS Budget_CM2_INR ,row_number() over (partition by month,asin order by try_cast(replace(replace(UNITS, \',\', \'\'), \'-\', \'\') as float) desc) rw from vahdam_db.maplemonk.vahdam_fy___25_budget____maplemonk___amazon_fy25_26 where lower(channel) = \'amazon\' and lower(GEO) = \'uae\' ) where rw = 1 group by 1,2 ), ASINDATE as ( with RECURSIVE date_range AS ( SELECT TO_DATE(\'2023-04-01\') AS date_value UNION ALL SELECT date_value + INTERVAL \'1 day\' FROM date_range WHERE date_value + INTERVAL \'1 day\' <= CURRENT_DATE() ), ASIN as ( select distinct asin_new as ASIN from vahdam_db.maplemonk.amazonads_uae_marketing ) SELECT date_value, ASIN FROM date_range cross join ASIN ), Amazonads as ( select date ,case when asin_new is null then \'SB\' else asin_new end as ASIN ,sum(ifnull(spend,0)) as Total_amazon_spend ,sum(ifnull(sales_usd,0)) as Total_amazon_sales from vahdam_db.maplemonk.amazonads_uae_marketing group by 1,2 order by date desc ), REMOVALDISPOSAL AS ( select date, SUM( case when lower(fee_type) = \'fbadisposalfee\' then amount else 0 end) as FBA_DISPOSAL_FEE, SUM(case when lower(fee_type) = \'fbaremovalfee\' then amount else 0 end) as FBA_REMOVAL_FEE from vahdam_db.maplemonk.vahdam_uae_removal_disposal_fees GROUP BY 1 ), Mapping as ( select * from (select \"Amazon UAE\" ,weight ,brand ,\"Mother SKU\" ,\"Common Name\" ,category ,\"SUB CATEGORY\" ,\"LOOSE/TEA BAG/ POWDER\" ,\"Common SKU Description\" ,\"COMMON SKU ID\" ,row_number() over (partition by \"Amazon USA\" order by \"Amazon USA\") as rw from vahdam_db.maplemonk.sku_mapping_raw_data) where rw = 1 or rw is null ), STORAGE AS ( SELECT case when COALESCE(A.MONTH,B.MONTH) = 1 then 13 else COALESCE(A.MONT