n MAPPING M on lower(coalesce(P.ASIN,B.ASIN,A.ASIN,AD.ASIN)) = lower(M.\"Amazon UAE\") LEFT JOIN STORAGE S ON MONTH(coalesce(P.date,ADJ.DATE,A.date,AD.date_value,B.Budget_month,R.DATE)) = S.MONTH AND YEAR(coalesce(P.date,ADJ.DATE,A.date,AD.date_value,B.Budget_month,R.DATE))= S.YEAR LEFT JOIN COB_LIB CL ON LOWER(coalesce(P.ASIN,ADJ.ASIN,A.asin,AD.ASIN,B.ASIN,M.\"Amazon UAE\"))=LOWER(CL.ASIN) order by Date desc;",
